function getNowInKolkata(){const now=new Date();const utcTime=now.getTime()+(now.getTimezoneOffset()*60000);const kolkataOffsetMs=5.5*3600000;return new Date(utcTime+kolkataOffsetMs);}
function getTomorrowDateObj(now){return new Date(now.getFullYear(),now.getMonth(),now.getDate()+1,0,0,0);}
