function closeDetailsModal(){if(DOM.detailsModal)DOM.detailsModal.classList.remove("active");}
function openSettingsModal(){if(!DOM.settingsModal)return;if(DOM.strictFilterToggle)DOM.strictFilterToggle.checked=state.strictCollegeFilter;if(DOM.customIncludeInput)DOM.customIncludeInput.value=state.customIncludeWords.join(", ");if(DOM.customExcludeInput)DOM.customExcludeInput.value=state.customExcludeWords.join(", ");DOM.settingsModal.classList.add("active");}
