function exportSingleEventIcs(s){const formatIcsDt=(d)=>{return d.getUTCFullYear()+
String(d.getUTCMonth()+1).padStart(2,"0")+
String(d.getUTCDate()).padStart(2,"0")+"T"+
String(d.getUTCHours()).padStart(2,"0")+
String(d.getUTCMinutes()).padStart(2,"0")+
String(d.getUTCSeconds()).padStart(2,"0")+"Z";};const icsContent=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Harsh's Library//MBBS College Timetable//EN","BEGIN:VEVENT",`UID:${s.uid}`,`DTSTAMP:${formatIcsDt(new Date())}`,`DTSTART:${formatIcsDt(s.startDate)}`,`DTEND:${formatIcsDt(s.endDate)}`,`SUMMARY:${s.title.replace(/,/g, "\\,")}`,`DESCRIPTION:${(s.cleanDesc || s.title).replace(/\n/g, "\\n").replace(/,/g, "\\,")}`,`LOCATION:${s.location.replace(/,/g, "\\,")}`,"END:VEVENT","END:VCALENDAR"].join("\r\n");const blob=new Blob([icsContent],{type:"text/calendar;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`${s.title.replace(/[^a-zA-Z0-9_-]/g, "_")}.ics`;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function setLoading(loading){state.isLoading=loading;if(DOM.loadingState)DOM.loadingState.style.display=loading?"block":"none";if(DOM.refreshBtn){if(loading)DOM.refreshBtn.classList.add("spinning");else DOM.refreshBtn.classList.remove("spinning");}}
