if(DOM.subjectPills){DOM.subjectPills.forEach((pill)=>{pill.addEventListener("click",()=>{DOM.subjectPills.forEach((p)=>p.classList.remove("active"));pill.classList.add("active");state.selectedSubject=pill.getAttribute("data-subject");updateActiveFilterCount();renderTimeline();});});}
