if(DOM.searchInput){DOM.searchInput.addEventListener("input",(e)=>{state.searchQuery=e.target.value;if(DOM.searchClear)DOM.searchClear.style.display=state.searchQuery?"block":"none";updateActiveFilterCount();renderTimeline();});}
if(DOM.searchClear){DOM.searchClear.addEventListener("click",()=>{state.searchQuery="";DOM.searchInput.value="";DOM.searchClear.style.display="none";updateActiveFilterCount();renderTimeline();});}
if(DOM.jumpPillBtns){DOM.jumpPillBtns.forEach((btn)=>{btn.addEventListener("click",()=>{const targetKey=btn.getAttribute("data-jump")||btn.getAttribute("data-jump-target");const now=getNowInKolkata();if(targetKey==="tomorrow"){const tomorrow=new Date(now);tomorrow.setDate(tomorrow.getDate()+1);jumpToDateAnchor(formatDateKey(tomorrow));}else if(targetKey==="next_monday"||targetKey==="next-monday"){const nextMon=new Date(now);const day=nextMon.getDay();const daysToAdd=day===0?1:(8-day);nextMon.setDate(nextMon.getDate()+daysToAdd);jumpToDateAnchor(formatDateKey(nextMon));}});});}
